def resolve(path, cwd, links):
    max_links = 8
    links_followed = 0

    if not path.startswith('/'):
        path = cwd + '/' + path if cwd != '/' else '/' + path

    components = path.split('/')
    current = []

    i = 0
    while i < len(components):
        comp = components[i]

        if comp == '' or comp == '.':
            i += 1
            continue
        elif comp == '..':
            if current:
                current.pop()
            i += 1
            continue
        else:
            current.append(comp)
            current_path = '/' + '/'.join(current)

            if current_path in links:
                if links_followed >= max_links:
                    return None

                links_followed += 1
                target = links[current_path]

                if target.startswith('/'):
                    current = []
                    target_components = target.split('/')
                else:
                    if len(current) > 1:
                        current = current[:-1]
                    else:
                        current = []
                    target_components = target.split('/')

                components = target_components + components[i+1:]
                i = 0
                continue

            i += 1

    if not current:
        return '/'
    return '/' + '/'.join(current)

